fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    // Pre-allocate a vector of the same length
    let mut b: Vec<char> = Vec::with_capacity(n);
    // Fill b by taking elements from a in reverse order
    let mut i = 0;
    while i < n {
        b.push(a[n - i - 1]);
        i += 1;
    }
    b
}

